t.script:
(function () {
    const steps = Array.from(document.querySelectorAll(".js-step"));
    const indicator = document.getElementById("iem_form_step_indicator");
    const prevBtn = document.getElementById("iem_prev_step");
    const nextBtn = document.getElementById("iem_next_step");
    const submitBtn = document.getElementById("iem_submit_form");
    const validateAccessBtn = document.getElementById("iem_validate_access");
    const searchDniBtn = document.getElementById("iem_search_dni");
    const clientMessage = document.getElementById("iem_form_client_message");
    const csrfTokenInput = document.querySelector('input[name="csrf_token"]');
    const accessPasswordInput = document.querySelector('input[name="access_password"]');
    const identificationTypeInput = document.querySelector('select[name="l10n_latam_identification_type_id"]');
    const dniInput = document.querySelector('input[name="vat"]');
    const firstNameInput = document.querySelector('input[name="first_name"]');
    const lastNameInput = document.querySelector('input[name="last_name"]');
    const uploadPhotoInput = document.getElementById("iem_upload_photo");
    const takePhotoInput = document.getElementById("iem_take_photo");
    const photoPreview = document.getElementById("iem_photo_preview");
    const predioSelect = document.querySelector('select[name="predio_id"]');
    const redSelect = document.querySelector('select[name="red_id"]');
    const discipuladoSelect = document.querySelector('select[name="discipulado_id"]');
    const celulaSelect = document.querySelector('select[name="celula_id"]');
    if (!steps.length || !indicator || !prevBtn || !nextBtn || !submitBtn) {
        return;
    }
    let currentStep = 0;
    const totalSteps = 3;
    let accessValidated = false;

    function showClientMessage(type, text) {
        if (!clientMessage) {
            return;
        }
        if (!text) {
            clientMessage.classList.add("d-none");
            clientMessage.textContent = "";
            clientMessage.classList.remove("alert-success", "alert-danger", "alert-warning", "alert-info");
            return;
        }
        clientMessage.classList.remove("d-none", "alert-success", "alert-danger", "alert-warning", "alert-info");
        clientMessage.classList.add(type === "success" ? "alert-success" : "alert-danger");
        clientMessage.textContent = text;
    }

    async function postAndReadJson(url, params) {
        const body = new URLSearchParams();
        Object.keys(params || {}).forEach((key) => {
            body.append(key, params[key] || "");
        });
        if (csrfTokenInput) {
            body.append("csrf_token", csrfTokenInput.value || "");
        }
        const response = await fetch(url, {
            method: "POST",
            headers: {
                "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
                "X-Requested-With": "XMLHttpRequest",
            },
            body: body.toString(),
            credentials: "same-origin",
        });
        return response.json();
    }

    function setStep(step) {
        currentStep = step;
        steps.forEach((el) => {
            const visible = Number(el.dataset.step) === currentStep;
            el.classList.toggle("d-none", !visible);
        });
        indicator.textContent = `Paso ${currentStep} de ${totalSteps}`;
        prevBtn.classList.toggle("d-none", currentStep === 1);
        if (currentStep === 0) {
            prevBtn.classList.add("d-none");
        }
        nextBtn.classList.toggle("d-none", currentStep === totalSteps || currentStep === 0);
        submitBtn.classList.toggle("d-none", currentStep !== totalSteps);
        if (validateAccessBtn) {
            validateAccessBtn.classList.toggle("d-none", currentStep !== 0);
        }
    }

    function filterByParent(selectElement, parentDataAttr, parentValue) {
        if (!selectElement) {
            return;
        }
        const options = Array.from(selectElement.options);
        options.forEach((opt) => {
            if (!opt.value) {
                opt.hidden = false;
                return;
            }
            if (!parentValue) {
                opt.hidden = true;
                return;
            }
            const optionParentValue = opt.dataset[parentDataAttr] || "";
            opt.hidden = optionParentValue !== parentValue;
        });
        if (selectElement.selectedOptions.length) {
            const selected = selectElement.selectedOptions[0];
            if (selected && selected.hidden) {
                selectElement.value = "";
            }
        }
    }

    function applyStep3Filters() {
        const predioValue = predioSelect ? predioSelect.value : "";
        filterByParent(redSelect, "predioId", predioValue);

        const redValue = redSelect ? redSelect.value : "";
        filterByParent(discipuladoSelect, "redId", redValue);

        const discipuladoValue = discipuladoSelect ? discipuladoSelect.value : "";
        filterByParent(celulaSelect, "discipuladoId", discipuladoValue);
    }

    function syncExclusiveImageInputs() {
        if (!uploadPhotoInput || !takePhotoInput) {
            return;
        }
        const hasUpload = uploadPhotoInput.files && uploadPhotoInput.files.length > 0;
        const hasTake = takePhotoInput.files && takePhotoInput.files.length > 0;
        if (hasUpload) {
            takePhotoInput.disabled = true;
            return;
        }
        if (hasTake) {
            uploadPhotoInput.disabled = true;
            return;
        }
        uploadPhotoInput.disabled = false;
        takePhotoInput.disabled = false;
    }

    function renderPhotoPreview(file) {
        if (!photoPreview) {
            return;
        }
        if (!file) {
            photoPreview.src = "";
            photoPreview.classList.add("d-none");
            return;
        }
        const reader = new FileReader();
        reader.onload = function (event) {
            photoPreview.src = event.target && event.target.result ? event.target.result : "";
            photoPreview.classList.toggle("d-none", !photoPreview.src);
        };
        reader.readAsDataURL(file);
    }

    if (predioSelect) {
        predioSelect.addEventListener("change", function () {
            if (redSelect) {
                redSelect.value = "";
            }
            if (discipuladoSelect) {
                discipuladoSelect.value = "";
            }
            if (celulaSelect) {
                celulaSelect.value = "";
            }
            applyStep3Filters();
        });
    }
    if (redSelect) {
        redSelect.addEventListener("change", function () {
            if (discipuladoSelect) {
                discipuladoSelect.value = "";
            }
            if (celulaSelect) {
                celulaSelect.value = "";
            }
            applyStep3Filters();
        });
    }
    if (discipuladoSelect) {
        discipuladoSelect.addEventListener("change", function () {
            if (celulaSelect) {
                celulaSelect.value = "";
            }
            applyStep3Filters();
        });
    }
    if (uploadPhotoInput) {
        uploadPhotoInput.addEventListener("change", function () {
            syncExclusiveImageInputs();
            const file = uploadPhotoInput.files && uploadPhotoInput.files.length ? uploadPhotoInput.files[0] : null;
            renderPhotoPreview(file);
        });
    }
    if (takePhotoInput) {
        takePhotoInput.addEventListener("change", function () {
            syncExclusiveImageInputs();
            const file = takePhotoInput.files && takePhotoInput.files.length ? takePhotoInput.files[0] : null;
            renderPhotoPreview(file);
        });
    }

    if (validateAccessBtn) {
        validateAccessBtn.addEventListener("click", async function () {
            try {
                const payload = await postAndReadJson("/church/registro/validate_access", {
                    access_password: accessPasswordInput ? accessPasswordInput.value : "",
                });
                if (!payload.ok) {
                    accessValidated = false;
                    showClientMessage("error", payload.message || "La clave no es correcta. El formulario no sera guardado.");
                    return;
                }
                accessValidated = true;
                showClientMessage("success", "Clave validada correctamente.");
                setStep(1);
            } catch (err) {
                showClientMessage("error", "No se pudo validar la clave en este momento.");
            }
        });
    }

    if (searchDniBtn) {
        searchDniBtn.addEventListener("click", async function () {
            try {
                const payload = await postAndReadJson("/church/registro/fetch_dni", {
                    l10n_latam_identification_type_id: identificationTypeInput ? identificationTypeInput.value : "",
                    vat: dniInput ? dniInput.value : "",
                });
                if (!payload.ok) {
                    showClientMessage("error", payload.message || "No se pudo consultar DNI.");
                    return;
                }
                if (firstNameInput && payload.first_name) {
                    firstNameInput.value = payload.first_name;
                }
                if (lastNameInput && payload.last_name) {
                    lastNameInput.value = payload.last_name;
                }
                showClientMessage("success", "Datos de DNI encontrados y cargados.");
            } catch (err) {
                showClientMessage("error", "No se pudo consultar DNI en este momento.");
            }
        });
    }

    nextBtn.addEventListener("click", async function () {
        if (currentStep === 1) {
            try {
                const payload = await postAndReadJson("/church/registro/check_dni", {
                    l10n_latam_identification_type_id: identificationTypeInput ? identificationTypeInput.value : "",
                    vat: dniInput ? dniInput.value : "",
                });
                if (!payload.ok) {
                    showClientMessage("error", payload.message || "Ya existe el documento de identidad registrado. El formulario no sera guardado.");
                    return;
                }
            } catch (err) {
                showClientMessage("error", "No se pudo validar el documento de identidad en este momento.");
                return;
            }
        }
        if (currentStep < totalSteps) {
            showClientMessage("", "");
            setStep(currentStep + 1);
        }
    });
    prevBtn.addEventListener("click", function () {
        if (currentStep > 1) {
            setStep(currentStep - 1);
        }
    });
    applyStep3Filters();
    syncExclusiveImageInputs();
    renderPhotoPreview(null);
    if (accessValidated) {
        setStep(1);
    } else {
        setStep(0);
    }
})();
